// 2. APLICAÇÃO DOS FILTROS
// =========================================================
const item = items[0].json;
let filters = [];
let needsCensoring = false;
let origemCensura = "Nenhuma";

// Função para adicionar filtro com segurança matemática
function addSafeFilter(x, y, w, h) {
    if (isBlind) {
        // Se estamos "cegos" (sem tamanho real), não arriscamos delogo.
        // Adicionamos um boxblur geral se ainda não tiver.
        if (!filters.some(f => f.includes('boxblur'))) {
            filters.push("boxblur=50:5"); 
        }
        return;
    }

    // Se temos tamanho, calculamos cortes precisos
    let safeX = Math.max(0, Math.floor(x));
    let safeY = Math.max(0, Math.floor(y));
    let safeW = Math.floor(w);
    let safeH = Math.floor(h);

    // Corta o excedente se passar da borda
    if (safeX + safeW > imgW) safeW = imgW - safeX;
    if (safeY + safeH > imgH) safeH = imgH - safeY;

    if (safeW > 0 && safeH > 0) {
        filters.push(`delogo=x=${safeX}:y=${safeY}:w=${safeW}:h=${safeH}`);
    }
}

