    for (const det of item.nudity.detections) {
        addSafeFilter(
            det.box.x1 * imgW,
            det.box.y1 * imgH,
            (det.box.x2 - det.box.x1) * imgW,
            (det.box.y2 - det.box.y1) * imgH
        );
