    // 1. Risco Cumulativo: Se a soma de (Sexo + Nudez + Sugestivo) > 30%
    const scoreTotal = activity + display + suggestive;
    const GATILHO_RISCO = 0.30; 

    // 2. Incerteza da IA: Se a certeza de segurança for menor que 99%
    // Isso pega aquelas imagens com "none: 0.94"
    const GATILHO_INCERTEZA = 0.99;

    if (scoreTotal > GATILHO_RISCO || safetyScore < GATILHO_INCERTEZA) {
        needsCensoring = true;
        tipoFiltro = "complex";

        if (scoreTotal > GATILHO_RISCO) origemCensura = `Panico_Risco_${scoreTotal.toFixed(2)}`;
        else origemCensura = `Panico_Preventivo_${safetyScore.toFixed(2)}`;

        // --- O FILTRO "NÉVOA LEITOSA" (THE MILKY FOG) ---
        // Passo a passo do que esse comando faz:
        // 1. [orig]boxblur=40:5 -> Borra tudo forte
        // 2. hue=s=0 -> Remove a cor (vira cinza) para matar tom de pele
        // 3. drawbox=...c=white@0.4 -> Pinta um branco transparente por cima (vira névoa/luz)
        // 4. [copy]lumakey -> Recorta o texto branco nítido
        // 5. overlay -> Cola o texto na névoa

        filters = `[0:v]split=2[original][copy];[original]boxblur=40:5,hue=s=0,drawbox=x=0:y=0:w=iw:h=ih:color=white@0.4:t=fill[foggy];[copy]lumakey=threshold=0.90:tolerance=0.15:softness=0.05[text_layer];[foggy][text_layer]overlay`;
    }
}

// =========================================================
// 3. RETORNO E DEBUG
// =========================================================
const tempName = `/tmp/censura_${item.paginaGlobal || Math.floor(Math.random() * 99999)}.jpg`;
const outputBinary = {};
if (binaryPack) outputBinary[binaryPropName] = binaryPack;

return {
    json: {
        ...item,
        needs_censoring: needsCensoring,
        ffmpeg_filter: filters,
        filter_type: tipoFiltro,
        censura_origem: origemCensura,
        temp_file_name: tempName,
        debug_info: item.nudity ? `Safety:${(item.nudity.none*100).toFixed(1)}% | RiskSum:${(item.nudity.sexual_activity+item.nudity.sexual_display+item.nudity.suggestive).toFixed(2)}` : "N/A"
    },
    binary: outputBinary
};
